// Gerado automaticamente. Edite os arquivos na raiz, não este arquivo.
const FILES = {"/index.html":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <!-- Instruções ao navegador: título, tamanho da tela e arquivos necessários. -->\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#174CA0\">\n  <meta name=\"description\" content=\"Calcule tamanho da amostra e intervalos de confiança, com explicações simples e claras.\">\n  <title>Estatística Aplicada — Calculadora</title>\n  <!-- CSS controla a aparência. JavaScript conecta os campos aos cálculos. -->\n  <link rel=\"stylesheet\" href=\"./assets/style.css\">\n  <script src=\"./src/calculos.js\" defer></script>\n  <script src=\"./src/app.js\" defer></script>\n  <script src=\"./src/exemplos.js\" defer></script>\n</head>\n<body>\n  <header class=\"cabecalho\">\n    <div class=\"largura topo\">\n      <a class=\"marca\" href=\"./\" aria-label=\"Estatística Aplicada — início\">\n        <span class=\"marca-sinal\" aria-hidden=\"true\">Σ</span>\n        <span>Estatística <strong>Aplicada</strong></span>\n      </a>\n      <span class=\"marca-extra\">Calculadora da disciplina</span>\n    </div>\n  </header>\n\n  <main class=\"largura\">\n    <div class=\"introducao\">\n      <span class=\"sobretitulo\">FÓRMULAS DA AULA</span>\n      <h1>Qual cálculo você precisa fazer?</h1>\n      <p>Escolha o assunto, preencha os valores do exercício e veja como chegar à resposta.</p>\n    </div>\n\n    <!-- As cinco abas são os cinco assuntos do index.html de referência. -->\n    <!-- data-aba indica qual seção abrir ao clicar no botão. -->\n    <nav class=\"abas\" aria-label=\"Escolher cálculo\">\n      <button type=\"button\" class=\"aba ativa\" data-aba=\"am\" aria-current=\"page\"><small>Tamanho da amostra</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ap\"><small>Tamanho da amostra</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"im\"><small>Intervalo de confiança</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ip\"><small>Intervalo de confiança</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"de\"><small>Ajuste da amostra</small><strong>Diminuir o erro</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ex\"><small>Treinar</small><strong>Exemplos</strong></button>\n    </nav>\n\n    <!-- Assunto 1: calcular quantas observações são necessárias para a média. -->\n    <section class=\"assunto visivel\" id=\"aba-am\" aria-labelledby=\"titulo-am\">\n      <h2 id=\"titulo-am\">Tamanho da amostra para a média</h2>\n      <p class=\"descricao\">Quantas observações preciso para estimar uma média com a precisão desejada?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-am\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"am-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"am-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"am\">Z = 1,96</output></div>\n          <label for=\"am-desvio\">Desvio-padrão populacional (σ)</label>\n          <input id=\"am-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"am-erro\">Erro amostral máximo aceito (Em)</label>\n          <input id=\"am-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a margem de erro\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = (Z · σ / Em)²</div><dl><dt>n</dt><dd>Tamanho mínimo da amostra</dd><dt>σ</dt><dd>Desvio-padrão populacional</dd><dt>Em</dt><dd>Erro máximo aceito</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 2: amostra necessária para estimar uma porcentagem. -->\n    <section class=\"assunto\" id=\"aba-ap\" aria-labelledby=\"titulo-ap\" hidden>\n      <h2 id=\"titulo-ap\">Tamanho da amostra para a proporção</h2>\n      <p class=\"descricao\">Quantas pessoas ou observações preciso para estimar uma porcentagem?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-ap\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ap-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ap-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ap\">Z = 1,96</output></div>\n          <label for=\"ap-p\">Proporção estimada (p), em %</label>\n          <input id=\"ap-p\" name=\"p\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a porcentagem\">\n          <label class=\"marcar\"><input type=\"checkbox\" name=\"desconhecida\" id=\"ap-desconhecida\"> Proporção desconhecida (usar 50%)</label>\n          <div class=\"dado-automatico\"><span>Complemento (1 − p)</span><output id=\"ap-complemento\">—</output></div>\n          <label for=\"ap-erro\">Erro da proporção (Ep), em %</label>\n          <input id=\"ap-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o erro em %\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = Z² · p · (1 − p) / Ep²</div><dl><dt>p</dt><dd>Proporção estimada</dd><dt>1 − p</dt><dd>Complemento da proporção</dd><dt>Ep</dt><dd>Erro da proporção, em decimal</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 3: intervalo entre dois valores para a média. -->\n    <section class=\"assunto\" id=\"aba-im\" aria-labelledby=\"titulo-im\" hidden>\n      <h2 id=\"titulo-im\">Intervalo de confiança para a média</h2>\n      <p class=\"descricao\">Entre quais valores pode estar a média verdadeira da população?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-im\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"im-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"im-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"im\">Z = 1,96</output></div>\n          <label for=\"im-media\">Média amostral (x̄)</label><input id=\"im-media\" name=\"media\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a média\">\n          <label for=\"im-desvio\">Desvio-padrão (σ ou s)</label><input id=\"im-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"im-n\">Tamanho da amostra (n)</label><input id=\"im-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Em = Z · σ / √n</div><div class=\"expressao\">IC = x̄ ± Em</div><dl><dt>x̄</dt><dd>Média da amostra</dd><dt>Em</dt><dd>Margem de erro calculada</dd><dt>n</dt><dd>Quantidade de observações</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 4: intervalo entre duas porcentagens. -->\n    <section class=\"assunto\" id=\"aba-ip\" aria-labelledby=\"titulo-ip\" hidden>\n      <h2 id=\"titulo-ip\">Intervalo de confiança para a proporção</h2>\n      <p class=\"descricao\">Entre quais porcentagens pode estar a proporção verdadeira da população?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-ip\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ip-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ip-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ip\">Z = 1,96</output></div>\n          <label for=\"ip-sucessos\">Quantidade ou porcentagem com a característica</label><input id=\"ip-sucessos\" name=\"sucessos\" inputmode=\"text\" autocomplete=\"off\" placeholder=\"Ex.: 922 ou 40%\">\n          <label for=\"ip-n\">Tamanho da amostra (n)</label><input id=\"ip-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o total pesquisado\">\n          <div class=\"dado-automatico\"><span>Proporção da amostra</span><output id=\"ip-proporcao\">—</output></div>\n          <label for=\"ip-padrao\">Padrão estabelecido (%) <span class=\"opcional\">— opcional</span></label><input id=\"ip-padrao\" name=\"padrao\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Somente se o exercício pedir\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">p = sucessos / n ou % / 100</div><div class=\"expressao\">Ep = Z · √[p(1 − p) / n]</div><div class=\"expressao\">IC = p ± Ep</div><dl><dt>p</dt><dd>Proporção da amostra</dd><dt>Ep</dt><dd>Margem de erro da proporção</dd><dt>n</dt><dd>Total pesquisado</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 5: a amostra cresce quando exigimos erro menor. -->\n    <section class=\"assunto\" id=\"aba-de\" aria-labelledby=\"titulo-de\" hidden>\n      <h2 id=\"titulo-de\">Diminuir o erro da média</h2>\n      <p class=\"descricao\">Se eu quiser um erro menor, quantas observações adicionais serão necessárias?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-de\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"de-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"de-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"de\">Z = 1,96</output></div>\n          <label for=\"de-desvio\">Desvio-padrão (σ ou s)</label><input id=\"de-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"de-n\">Tamanho atual da amostra (n)</label><input id=\"de-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o tamanho atual\">\n          <div class=\"dado-automatico\"><span>Erro atual (Em)</span><output id=\"de-atual\">—</output></div>\n          <label for=\"de-k\">Dividir o erro por quantas vezes?</label><input id=\"de-k\" name=\"k\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite um valor maior que 1\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Novo Em = Em / k</div><div class=\"expressao\">Novo n = (Z · σ / Novo Em)²</div><dl><dt>k</dt><dd>Quantas vezes o erro vai diminuir</dd><dt>Em</dt><dd>Margem de erro atual</dd><dt>n</dt><dd>Quantidade de observações</dd></dl><p class=\"nota-formula\">Ao reduzir o erro pela metade, precisamos de aproximadamente 4 vezes mais observações.</p></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <section class=\"assunto\" id=\"aba-ex\" aria-labelledby=\"titulo-ex\" hidden>\n      <h2 id=\"titulo-ex\">Exemplos para praticar</h2>\n      <p class=\"descricao\">Exercícios adaptados dos PDFs da aula, com valores diferentes. Preencha os dados e clique em Calcular quando quiser conferir.</p>\n      <div id=\"lista-exemplos\"></div>\n    </section>\n\n    <footer class=\"rodape\"><span>Uma ferramenta de apoio aos exercícios de Estatística Aplicada.</span><span>RFB · 2026</span></footer>\n  </main>\n</body>\n</html>\n","/assets/style.css":"/*\n * VISUAL — modifique cores e espaços aqui, sem mexer nas fórmulas.\n * Apenas azul, tons neutros e branco. Não usamos bibliotecas de estilo.\n */\n/* Apelidos das cores usados no site inteiro. */\n:root { color-scheme: light; --azul:#2157af; --azul-forte:#153f85; --azul-claro:#edf3fd;\n  --texto:#192638; --secundario:#617188; --linha:#dbe3ef; --fundo:#f7f9fc; --branco:#fff; }\n* { box-sizing:border-box; }\n/* Fonte, cor do texto e fundo geral. */\nbody { margin:0; font:15px/1.55 system-ui,-apple-system,\"Segoe UI\",Arial,sans-serif; background:var(--fundo); color:var(--texto); }\nbutton, input, select { font:inherit; }\nbutton { cursor:pointer; }\n[hidden] { display:none !important; }\n/* Centraliza o conteúdo e limita sua largura. */\n.largura { width:min(1130px,calc(100% - 44px)); margin-inline:auto; }\n/* Barra do topo e identificação. */\n.cabecalho { background:#fff; border-bottom:1px solid var(--linha); }\n.topo { min-height:73px; display:flex; justify-content:space-between; align-items:center; gap:20px; }\n.marca { display:inline-flex; align-items:center; gap:11px; color:var(--texto); text-decoration:none; font-size:19px; letter-spacing:-.55px; }\n.marca strong { color:var(--azul); font-weight:700; }\n.marca-sinal { display:grid; place-items:center; background:var(--azul-forte); color:white; width:37px; height:37px; border-radius:9px; font-size:22px; font-weight:650; }\n.marca-extra { color:var(--secundario); font-size:13px; }\n/* Título e descrição da página. */\n.introducao { padding:40px 0 23px; }\n.sobretitulo { font-size:11px; font-weight:800; letter-spacing:1.5px; color:var(--azul); }\nh1 { font-size:clamp(27px,3.8vw,38px); letter-spacing:-1.1px; line-height:1.2; margin:9px 0 9px; font-weight:750; }\n.introducao p { margin:0; color:var(--secundario); max-width:660px; }\n/* Organiza os botões de assunto. */\n.abas { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:9px; margin:0 0 33px; }\n.aba { min-width:0; text-align:left; display:flex; flex-direction:column; justify-content:center; gap:2px; padding:13px 15px; border-radius:10px; border:1px solid var(--linha); color:var(--texto); background:white; min-height:70px; transition:border-color .12s,background .12s; }\n.aba small { color:var(--secundario); font-size:11px; line-height:1.25; }\n.aba strong { font-size:14px; font-weight:680; line-height:1.2; }\n.aba:hover { border-color:#a5bde7; background:#f9fbff; }\n.aba.ativa { border-color:var(--azul); background:var(--azul-claro); box-shadow:inset 0 3px var(--azul); }\n.aba.ativa strong { color:var(--azul-forte); }\n.assunto > h2 { margin:0 0 4px; font-size:23px; letter-spacing:-.6px; line-height:1.3; }\n.descricao { margin:0 0 22px; color:var(--secundario); }\n/* Coloca dados e fórmula lado a lado. */\n.colunas { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,.95fr); gap:19px; align-items:start; }\n/* Caixas brancas que agrupam informações. */\n.cartao { background:var(--branco); border:1px solid var(--linha); border-radius:13px; padding:26px 28px; box-shadow:0 3px 16px rgba(25,50,80,.025); }\n.cartao h3 { font-size:16px; margin:0 0 18px; font-weight:740; letter-spacing:-.2px; }\n/* Campos do formulário em uma coluna. */\n.dados { display:flex; flex-direction:column; }\n.dados > label:not(.marcar) { font-weight:630; font-size:13px; margin:0 0 6px; }\n.dados > input, .confianca select { width:100%; border:1px solid #cdd8e7; border-radius:7px; padding:11px 13px; height:44px; color:var(--texto); background:white; outline:none; margin:0 0 17px; }\n.dados > input::placeholder { color:#97a3b2; }\n.dados > input:focus, .confianca select:focus { border-color:var(--azul); box-shadow:0 0 0 3px rgba(33,87,175,.11); }\n.dados > input:disabled { background:#f4f6fa; color:var(--secundario); }\n/* Lista de confiança e valor Z ao lado. */\n.confianca { display:flex; align-items:start; gap:12px; }\n.confianca select { flex:1; min-width:0; }\n.confianca output { flex:0 0 auto; margin-top:4px; padding:7px 11px; color:var(--azul-forte); background:var(--azul-claro); border-radius:7px; font-weight:700; font-size:12px; }\n.marcar { display:flex; align-items:center; gap:9px; margin:-4px 0 18px; color:var(--texto); font-size:13px; cursor:pointer; }\n.marcar input { width:17px; height:17px; accent-color:var(--azul); }\n/* Resultados automáticos que o usuário não edita. */\n.dado-automatico { display:flex; align-items:center; justify-content:space-between; gap:12px; background:#f4f7fc; border:1px solid #e5eaf4; border-radius:7px; padding:11px 13px; margin:0 0 17px; font-size:13px; color:var(--secundario); }\n.dado-automatico output { color:var(--azul-forte); font-weight:740; text-align:right; }\n.opcional { color:var(--secundario); font-weight:400; }\n/* Aparência dos botões. */\n.acoes { display:flex; gap:10px; margin-top:6px; }\n.acoes button { border-radius:8px; border:1px solid var(--linha); height:44px; padding:0 22px; font-weight:700; }\n.primario { color:white; background:var(--azul); border-color:var(--azul) !important; }\n.primario:hover { background:var(--azul-forte); }\n.limpar { background:white; color:var(--secundario); }\n.limpar:hover { border-color:#93a8c9; color:var(--texto); }\n/* Mensagem vermelha quando o valor é inválido. */\n.erro { background:#fff1ef; border:1px solid #efbeb8; border-radius:8px; color:#9b3127; padding:10px 12px; margin-bottom:10px; font-size:13px; }\n/* Aparência da expressão matemática. */\n.formula .expressao { display:block; color:var(--azul-forte); background:#f2f6fc; border:1px solid #e0e9f8; border-radius:8px; font-family:\"Cambria Math\",Georgia,serif; font-size:clamp(18px,2.2vw,24px); text-align:center; padding:17px 10px; margin:12px 0; overflow-wrap:anywhere; }\n.formula dl { display:grid; grid-template-columns:65px 1fr; gap:8px 14px; font-size:13px; margin:23px 0 0; }\n.formula dt { color:var(--azul-forte); font-weight:740; }\n.formula dd { margin:0; color:var(--secundario); }\n.nota-formula { color:var(--secundario); font-size:13px; margin:19px 0 0; }\n/* Painel da resposta calculada. */\n.resultado { border:1px solid #bfceea; border-radius:13px; background:white; padding:27px 28px; margin-top:19px; margin-bottom:20px; box-shadow:0 3px 16px rgba(25,50,80,.025); }\n.resposta-superior { font-size:11px; letter-spacing:1.3px; font-weight:800; color:var(--azul); }\n.numero-resposta { display:block; color:var(--azul-forte); font-size:clamp(30px,4.3vw,43px); letter-spacing:-1.1px; line-height:1.25; padding:8px 0 3px; overflow-wrap:anywhere; }\n.frase-resposta { margin:5px 0 18px; max-width:760px; color:#3a4a60; }\n/* Organiza os valores intermediários. */\n.extras { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 24px; border-top:1px solid var(--linha); margin:13px 0 12px; padding-top:8px; }\n.extra-linha { display:flex; gap:12px; align-items:center; justify-content:space-between; border-bottom:1px solid #eef2f7; padding:9px 0; font-size:13px; }\n.extra-linha span { color:var(--secundario); }\n.extra-linha strong { color:var(--texto); text-align:right; }\n.aviso { background:var(--azul-claro); color:var(--azul-forte); padding:12px 14px; border-radius:7px; font-size:13px; margin:18px 0; }\n/* Resolução que pode abrir e fechar. */\n.passos { border-top:1px solid var(--linha); margin:20px 0 0; padding-top:12px; }\n.passos summary { color:var(--azul-forte); font-weight:700; cursor:pointer; padding:5px 0; }\n.passos summary:hover { text-decoration:underline; }\n.passos ol { margin:14px 0 0; padding:0 0 0 24px; }\n.passos li { padding:4px 0 13px 8px; }\n.passos li::marker { color:var(--azul); font-weight:700; }\n.passos li strong { font-size:14px; }\n.passos li p { font-size:13px; color:var(--secundario); margin:4px 0 0; overflow-wrap:anywhere; }\n/* Identificação no fim da página. */\n.rodape { display:flex; justify-content:space-between; gap:14px; border-top:1px solid var(--linha); padding:24px 0 30px; margin-top:58px; color:var(--secundario); font-size:12px; }\n:focus-visible { outline:3px solid #79a8f4; outline-offset:2px; }\n/* Adapta a largura para tablets. */\n@media (max-width: 860px) {\n  .colunas { grid-template-columns:1fr; }\n  .abas { gap:7px; }\n  .aba { padding:11px 9px; min-height:72px; }\n  .aba strong { font-size:13px; }\n}\n/* Adapta a página para celular. */\n@media (max-width: 620px) {\n  .largura { width:min(100% - 28px,500px); }\n  .topo { min-height:63px; }\n  .marca { font-size:17px; }\n  .marca-extra { display:none; }\n  .introducao { padding:28px 0 19px; }\n  .introducao p { font-size:14px; }\n  .abas { grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; margin-bottom:25px; }\n  .aba { min-height:59px; padding:10px 13px; }\n\n  .assunto > h2 { font-size:21px; }\n  .descricao { font-size:14px; margin-bottom:17px; }\n  .cartao { padding:21px 18px; }\n  .colunas { gap:12px; }\n  .resultado { padding:22px 18px; margin-top:13px; }\n  .extras { grid-template-columns:1fr; }\n  .rodape { margin-top:40px; flex-direction:column; gap:5px; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior:auto !important; transition:none !important; } }\n\n/* Exemplos ficam separados da tela de cálculo. */\n.grupo-exemplos { margin:0 0 28px; }\n.grupo-exemplos h3 { font-size:17px; margin:0 0 12px; }\n.grade-exemplos { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }\n.exemplo-card { padding:19px 21px; display:flex; flex-direction:column; }\n.exemplo-card h4 { margin:0; font-size:15px; color:var(--azul-forte); }\n.exemplo-card p { margin:9px 0 15px; color:var(--secundario); overflow-wrap:anywhere; }\n.exemplo-acoes { flex-wrap:wrap; margin-top:auto; }\n.exemplo-acoes button { min-height:44px; height:auto; padding:9px 14px; }\n@media (max-width:620px) { .grade-exemplos { grid-template-columns:1fr; } }\n\n/* Botão de precisão: muda só a aparência dos números. */\n.precisao { background:transparent; color:var(--azul-forte); border:1px solid var(--linha); border-radius:7px; padding:7px 12px; font-size:13px; font-weight:650; margin:4px 0 9px; }\n.precisao:hover { background:var(--azul-claro); }\n/* Permite quebrar números longos em telas pequenas. */\n.extra-linha > * { min-width:0; overflow-wrap:anywhere; }\n\n/* Gráfico do intervalo de confiança: três números e uma régua azul. */\n.grafico-ic { margin:20px 0 0; padding:18px 0 2px; border-top:1px solid var(--linha); min-width:0; }\n.grafico-ic figcaption { font-size:14px; font-weight:700; color:var(--texto); }\n/* Linha cinza de referência e trecho azul entre os dois limites. */\n.grafico-regua { position:relative; height:42px; margin:14px 0 2px; }\n.grafico-regua::before { content:\"\"; position:absolute; top:19px; left:5%; right:5%; height:2px; background:var(--linha); }\n.grafico-faixa { position:absolute; left:16.6667%; right:16.6667%; top:18px; height:4px; background:var(--azul); border-radius:2px; }\n/* Pequenos traços verticais marcam as pontas do intervalo. */\n.grafico-faixa::before,.grafico-faixa::after { content:\"\"; position:absolute; top:-6px; width:2px; height:16px; background:var(--azul-forte); }\n.grafico-faixa::before { left:0; }.grafico-faixa::after { right:0; }\n/* A bolinha marca a estimativa da amostra, bem no meio da régua. */\n.grafico-centro { position:absolute; top:14px; left:50%; width:12px; height:12px; transform:translateX(-50%); border-radius:50%; background:var(--azul-forte); box-shadow:0 0 0 3px white; }\n.grafico-regua.pontual .grafico-faixa { display:none; }\n/* Os textos podem quebrar linha, inclusive com dez casas decimais. */\n.grafico-rotulos { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; text-align:center; }\n.grafico-rotulos > div { min-width:0; overflow-wrap:anywhere; }\n.grafico-rotulos span { display:block; color:var(--secundario); font-size:11px; }\n.grafico-rotulos strong { display:block; color:var(--azul-forte); font-size:clamp(12px,2vw,16px); font-variant-numeric:tabular-nums; margin-top:3px; }\n.grafico-nota { color:var(--secundario); font-size:12px; margin:16px 0 0; }\n\n/* IMPRESSÃO: o botão combina com a interface azul. O relatório não aparece na tela. */\n.imprimir-pdf { display:inline-flex; align-items:center; justify-content:center; min-height:44px; margin-top:18px; padding:10px 16px; border:1px solid var(--azul); border-radius:8px; color:var(--azul-forte); background:white; font-size:13px; font-weight:700; }\n.imprimir-pdf:hover { background:var(--azul-claro); }\n.relatorio-impressao { display:none; }\n\n/* @page define o papel e as margens. @media print só funciona ao imprimir. */\n@page { size:A4; margin:14mm; }\n@media print {\n  /* Folha branca, letras legíveis e sem navegação ou campos editáveis. */\n  body { background:white; color:#192638; font-size:10pt; line-height:1.4; }\n  .largura { width:100%; max-width:none; margin:0; }\n  .cabecalho, .introducao, .abas, .rodape, .assunto > h2,\n  .assunto > .descricao, .assunto > .colunas, #aba-ex { display:none !important; }\n  .assunto[hidden], .resultado[hidden] { display:none !important; }\n  .resultado { margin:0; padding:0; border:0; border-radius:0; box-shadow:none; }\n  /* Imprime somente a cópia preparada do resultado atual. */\n  .resultado > :not(.relatorio-impressao) { display:none !important; }\n  .relatorio-impressao { display:block; }\n  .relatorio-marca { color:#153f85; font-size:9pt; font-weight:800; letter-spacing:.8px; margin:0 0 5pt; }\n  .relatorio-impressao h2 { font-size:18pt; line-height:1.2; margin:0 0 12pt; }\n  .relatorio-bloco { border-top:1px solid #dbe3ef; padding-top:8pt; margin-top:9pt; }\n  .relatorio-bloco h3 { font-size:11pt; margin:0 0 6pt; break-after:avoid; }\n  .relatorio-dados { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:3pt 12pt; margin:0; }\n  .relatorio-dados dt { color:#465970; }\n  .relatorio-dados dd { margin:0; font-weight:600; overflow-wrap:anywhere; }\n  .relatorio-formula { margin:3pt 0; color:#153f85; font-size:12pt; overflow-wrap:anywhere; }\n  .relatorio-impressao .numero-resposta { font-size:22pt; padding:0; }\n  .relatorio-impressao .frase-resposta { margin:5pt 0 8pt; }\n  .relatorio-impressao .extras { grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 12pt; margin:4pt 0; padding-top:2pt; }\n  .relatorio-impressao .extra-linha { padding:4pt 0; font-size:9pt; break-inside:avoid; }\n  .relatorio-impressao .grafico-ic { margin:8pt 0; padding:6pt 0; break-inside:avoid; }\n  .relatorio-impressao .grafico-regua { margin:2pt 0; }\n  .relatorio-impressao .grafico-faixa, .relatorio-impressao .grafico-centro, .relatorio-impressao .grafico-regua { print-color-adjust:exact; -webkit-print-color-adjust:exact; }\n  .relatorio-impressao .grafico-nota { margin:5pt 0 0; }\n  .relatorio-impressao .aviso { padding:6pt; margin:6pt 0; border:1px solid #dbe3ef; break-inside:avoid; }\n  .relatorio-impressao .passos ol { margin:4pt 0 0; }\n  .relatorio-impressao .passos li { padding:2pt 0 5pt 4pt; break-inside:avoid; }\n  .relatorio-impressao .passos li p { margin:2pt 0 0; font-size:9pt; }\n}\n\n/* Seletor de precisão: três escolhas, com destaque azul na opção selecionada. */\n.precisao-opcoes { display:flex; flex-wrap:wrap; gap:6px; margin:4px 0 9px; }\n.precisao-opcoes .precisao { margin:0; min-height:36px; }\n.precisao-opcoes .precisao[aria-pressed=\"true\"] { background:var(--azul-claro); border-color:var(--azul); color:var(--azul-forte); }\n.relatorio-precisao { font-size:9pt; color:var(--secundario); margin:0 0 8pt; }\n\n/* Resolução matemática: cada linha é uma conta separada, como no caderno. */\n.contas-formula { display:grid; gap:8px; margin:12px 0 4px; }\n.conta-formula { min-width:0; padding:11px 12px; background:#f4f7fc; border:1px solid var(--linha); border-radius:8px; break-inside:avoid; }\n.conta-rotulo { display:block; font-size:12px; color:var(--secundario); margin-bottom:7px; }\n.conta-expressao { display:flex; flex-wrap:wrap; align-items:center; gap:4px; color:var(--azul-forte); font-family:\"Cambria Math\",Georgia,serif; font-size:clamp(15px,2.2vw,21px); line-height:1.4; min-width:0; }\n.conta-texto { min-width:0; max-width:100%; overflow-wrap:anywhere; white-space:pre-wrap; }\n/* A linha entre numerador e denominador cria uma fração visual sem biblioteca. */\n.conta-fracao { display:inline-flex; flex-direction:column; align-items:stretch; text-align:center; min-width:0; max-width:100%; overflow-wrap:anywhere; }\n.conta-numerador { display:block; padding:0 5px 3px; border-bottom:1.5px solid currentColor; }\n.conta-denominador { display:block; padding:3px 5px 0; }\n@media print {\n  .relatorio-impressao .contas-formula { gap:4pt; margin:4pt 0; }\n  .relatorio-impressao .conta-formula { background:white; border:1px solid #dbe3ef; padding:5pt 7pt; }\n  .relatorio-impressao .conta-rotulo { font-size:8pt; margin-bottom:2pt; }\n  .relatorio-impressao .conta-expressao { font-size:11pt; }\n}\n","/src/calculos.js":"/*\n * CONTAS ESTATÍSTICAS — edite aqui se uma fórmula estiver errada.\n * Não depende do navegador: podemos testar este arquivo sozinho.\n * O resultado guarda números sem arredondar. A tela arredonda só ao exibir.\n */\n(function (global) {\n  'use strict';\n\n  // Tabela Z usada nos PDFs da professora.\n  const TABELA_Z = Object.freeze({90: 1.645, 95: 1.96, 99: 2.575});\n\n  // Aceita 1,25 (decimal), 1.250 (milhar) e 1.250,50.\n  // Números inválidos, infinitos e campos vazios geram mensagens legíveis.\n  function numero(texto, nome = 'Valor') {\n    if (typeof texto === 'number') {\n      if (Number.isFinite(texto)) return texto;\n      throw new Error(`${nome}: informe um número válido.`);\n    }\n    const original = String(texto ?? '').trim().replace(/\\s/g, '');\n    if (!original) throw new Error(`${nome}: preencha este campo.`);\n    let ajustado = original;\n    if (/^[+-]?\\d{1,3}(?:\\.\\d{3})+,(?:\\d+)$/.test(original)) {\n      ajustado = original.replace(/\\./g, '').replace(',', '.');\n    } else if (/^[+-]?[1-9]\\d{0,2}(?:\\.\\d{3})+$/.test(original)) {\n      ajustado = original.replace(/\\./g, '');\n    } else if (/^[+-]?(?:\\d+(?:[.,]\\d+)?|[.,]\\d+)$/.test(original)) {\n      ajustado = original.replace(',', '.');\n    } else {\n      throw new Error(`${nome}: digite apenas um número (por exemplo, 1,25).`);\n    }\n    const resultado = Number(ajustado);\n    if (!Number.isFinite(resultado)) throw new Error(`${nome}: número grande demais.`);\n    return resultado;\n  }\n\n  // Verifica se um valor passa do mínimo permitido.\n  function validarMaior(valor, nome, limite = 0) {\n    if (valor <= limite) throw new Error(`${nome}: deve ser maior que ${limite}.`);\n    return valor;\n  }\n  // Contagens precisam ser inteiras: não existe meia pessoa pesquisada.\n  function inteiro(valor, nome, permiteZero = false) {\n    if (!Number.isSafeInteger(valor) || valor < (permiteZero ? 0 : 1)) {\n      throw new Error(`${nome}: digite um número inteiro ${permiteZero ? 'a partir de zero' : 'maior que zero'}.`);\n    }\n    return valor;\n  }\n  // Divide por 100: 30% vira 0,30 para entrar na fórmula.\n  function porcentagem(valor, nome, permiteZero = false) {\n    if (valor < (permiteZero ? 0 : Number.MIN_VALUE) || valor >= 100) {\n      throw new Error(`${nome}: informe uma porcentagem ${permiteZero ? 'de 0 a menos de 100' : 'maior que 0 e menor que 100'}.`);\n    }\n    return valor / 100;\n  }\n  // Procura o número Z na tabela, usando a confiança escolhida.\n  function valorCritico(confianca) {\n    if (!Object.prototype.hasOwnProperty.call(TABELA_Z, confianca)) {\n      throw new Error('Grau de confiança: escolha 90%, 95% ou 99%.');\n    }\n    return TABELA_Z[confianca];\n  }\n  // Amostras devem ser arredondadas para cima. O ajuste só evita\n  // erros minúsculos de representação binária: 600,0000000000001 -> 600.\n  function amostraInteira(valor) {\n    if (!Number.isFinite(valor) || valor > Number.MAX_SAFE_INTEGER) {\n      throw new Error('Amostra calculada grande demais. Revise a margem de erro.');\n    }\n    return Math.max(1, Math.ceil(valor - 1e-10));\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: TAMANHO DA AMOSTRA PARA A MÉDIA\n  // n = (Z × desvio-padrão / erro máximo)².\n  function amostraMedia({confianca = 95, desvio, erro}) {\n    const z = valorCritico(confianca);\n    validarMaior(desvio, 'Desvio-padrão');\n    validarMaior(erro, 'Erro máximo');\n    // Elevar ao quadrado significa multiplicar o número por ele mesmo.\n    const exato = (z * desvio / erro) ** 2;\n    return {z, desvio, erro, exato, n: amostraInteira(exato)};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: TAMANHO DA AMOSTRA PARA A PROPORÇÃO\n  // p e Ep são percentuais na tela, convertidos para decimal antes da conta.\n  function amostraProporcao({confianca = 95, percentual, erro}) {\n    const z = valorCritico(confianca);\n    const p = porcentagem(percentual, 'Proporção estimada');\n    const ep = porcentagem(erro, 'Erro da proporção');\n    // O complemento é o que falta para completar 100%.\n    const q = 1 - p;\n    const exato = z ** 2 * p * q / ep ** 2;\n    return {z, p, q, ep, exato, n: amostraInteira(exato)};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: INTERVALO DE CONFIANÇA DA MÉDIA\n  // Em = Z × σ / √n. Depois subtraímos e somamos Em à média.\n  function intervaloMedia({confianca = 95, media, desvio, n}) {\n    const z = valorCritico(confianca);\n    if (desvio < 0) throw new Error('Desvio-padrão: não pode ser negativo.');\n    inteiro(n, 'Tamanho da amostra');\n    // Math.sqrt calcula a raiz quadrada. A margem mostra a distância até os limites.\n    const margem = z * desvio / Math.sqrt(n);\n    // Subtrai e soma a margem para obter os extremos.\n    const inferior = media - margem, superior = media + margem;\n    if (![inferior, superior].every(Number.isFinite)) throw new Error('Resultado grande demais. Revise os dados.');\n    return {z, media, desvio, n, margem, inferior, superior, amplitude: superior - inferior, aviso: n <= 30 ? 'Se o desvio é amostral e n é pequeno, pode ser necessário usar t de Student. Esta calculadora segue o método Z da aula.' : ''};\n  }\n\n  // Lê o mesmo campo de duas maneiras: 40 significa 40 pessoas; 40% significa 40 de cada 100.\n  // O símbolo % é o sinal de que a pessoa já informou a proporção, não uma contagem.\n  // n continua sendo o total pesquisado. Não arredondamos nem inventamos pessoas.\n  function lerCaracteristica(texto, n) {\n    inteiro(n, 'Tamanho da amostra');\n    const entrada = String(texto ?? '').trim();\n    if (entrada.endsWith('%')) {\n      // Retira somente o último símbolo %. Um texto como 40%% continua inválido.\n      const percentual = numero(entrada.slice(0, -1), 'Porcentagem com a característica');\n      if (percentual < 0 || percentual > 100) throw new Error('Porcentagem com a característica: use um valor entre 0% e 100%.');\n      return {p: percentual / 100, sucessos: null, percentualInformado: percentual};\n    }\n    // Sem %, o número precisa representar uma quantidade inteira de pessoas ou itens.\n    const sucessos = inteiro(numero(texto, 'Quantidade com a característica'), 'Quantidade com a característica', true);\n    if (sucessos > n) throw new Error('Quantidade com a característica: não pode ultrapassar o total pesquisado.');\n    return {p: sucessos / n, sucessos, percentualInformado: null};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: INTERVALO DE CONFIANÇA DA PROPORÇÃO\n  // p = pessoas com a característica / pessoas pesquisadas.\n  // Ep = Z × raiz[p(1-p)/n]. Não alteramos os limites artificialmente.\n  function intervaloProporcao({confianca = 95, sucessos, n, padrao = null}) {\n    const z = valorCritico(confianca);\n    // Descobre p pela quantidade ou usa diretamente a porcentagem informada.\n    const dado = lerCaracteristica(sucessos, n);\n    const p = dado.p, q = 1 - p;\n    // Aplica a fórmula da incerteza da proporção, usando a tabela Z.\n    const margem = z * Math.sqrt(p * q / n);\n    const inferior = p - margem, superior = p + margem;\n    // Uma lista que guarda alertas sem impedir a exibição do cálculo.\n    const avisos = [];\n    // Na entrada percentual, p vezes n serve apenas para avaliar a aproximação.\n    if (p * n < 5 || q * n < 5) avisos.push('Poucos casos em um dos grupos: este método de aproximação pode não ser adequado.');\n    if (inferior < 0 || superior > 1) avisos.push('A fórmula produziu um limite fora de 0% a 100%. Confira a adequação do método.');\n    if (padrao !== null && (padrao < 0 || padrao > 100)) throw new Error('Padrão estabelecido: use uma porcentagem entre 0 e 100.');\n    return {z, n, sucessos: dado.sucessos, percentualInformado: dado.percentualInformado, p, q, margem, inferior, superior, padrao, avisos,\n      atendePadrao: padrao === null ? null : superior * 100 < padrao};\n  }\n\n  // FUNCIONAMENTO DA FÓRMULA: DIMINUIR O ERRO\n  // Se o erro vai ser dividido por k, a amostra cresce cerca de k² vezes.\n  function diminuirErro({confianca = 95, desvio, n, fator}) {\n    const z = valorCritico(confianca);\n    validarMaior(desvio, 'Desvio-padrão');\n    inteiro(n, 'Tamanho atual da amostra');\n    validarMaior(fator, 'Dividir o erro por', 1);\n    // Descobre o erro antes de reduzir; depois divide pelo fator escolhido.\n    const erroAtual = z * desvio / Math.sqrt(n);\n    const novoErro = erroAtual / fator;\n    const exato = (z * desvio / novoErro) ** 2;\n    const novoN = amostraInteira(exato);\n    return {z, desvio, n, fator, erroAtual, novoErro, exato, novoN, adicionar: novoN - n};\n  }\n\n  // Compartilha as funções com a interface e os testes.\n  global.Calculos = Object.freeze({numero, inteiro, porcentagem, valorCritico, lerCaracteristica,\n    amostraInteira, amostraMedia, amostraProporcao, intervaloMedia,\n    intervaloProporcao, diminuirErro});\n})(globalThis);\n","/src/app.js":"/*\n * INTERFACE — botões, campos e apresentação dos resultados.\n * As fórmulas ficam em calculos.js; aqui só lemos entradas e mostramos a conta.\n * Para trocar o nome de um campo, altere seu <label> no index.html.\n */\n(() => {\n  'use strict';\n  // M é um apelido para as funções de matemática de calculos.js.\n  const M = globalThis.Calculos;\n  // Busca um elemento do HTML pelo nome único dele (id).\n  const $ = id => document.getElementById(id);\n  // Converte números para texto com vírgula brasileira.\n  const fmt = (n, casas = 4) => n.toLocaleString('pt-BR', {maximumFractionDigits: casas});\n  // Multiplica o decimal por 100 e acrescenta o símbolo de porcentagem.\n  const percentual = (p, casas = 2) => `${fmt(p * 100, casas)}%`;\n  // Lê o campo preenchido e verifica se o texto é um número.\n  const lido = (form, nome, titulo) => M.numero(form.elements.namedItem(nome).value, titulo);\n  // Lê a confiança escolhida e a transforma em número.\n  const confianca = form => Number(form.elements.namedItem('confianca').value);\n\n  // Trocar assunto não apaga o que foi digitado nas outras abas.\n  function abrirAba(id) {\n    for (const secao of document.querySelectorAll('.assunto')) {\n      const selecionada = secao.id === `aba-${id}`;\n      secao.hidden = !selecionada;\n      secao.classList.toggle('visivel', selecionada);\n    }\n    for (const botao of document.querySelectorAll('.aba')) {\n      const selecionado = botao.dataset.aba === id;\n      botao.classList.toggle('ativa', selecionado);\n      if (selecionado) botao.setAttribute('aria-current', 'page');\n      else botao.removeAttribute('aria-current');\n    }\n  }\n\n  // Exibe o valor Z sem pedir ao estudante que procure uma tabela.\n  function atualizarZ(form) {\n    const id = form.id.slice(5);\n    const saída = document.querySelector(`[data-z=\"${id}\"]`);\n    saída.textContent = `Z = ${fmt(M.valorCritico(confianca(form)), 3)}`;\n  }\n\n  // Campos descobertos automaticamente: o estudante não consegue editá-los.\n  function atualizarComplemento() {\n    const form = $('form-ap');\n    const desconhecida = $('ap-desconhecida').checked;\n    const campo = $('ap-p');\n    campo.disabled = desconhecida;\n    campo.placeholder = desconhecida ? '50' : 'Digite a porcentagem';\n    if (desconhecida) { $('ap-complemento').textContent = '50%'; return; }\n    try {\n      const p = M.porcentagem(M.numero(campo.value), 'Proporção');\n      $('ap-complemento').textContent = percentual(1 - p);\n    } catch (_) { $('ap-complemento').textContent = '—'; }\n  }\n  // Divide a quantidade com a característica pelo total pesquisado.\n  function atualizarProporcao() {\n    try {\n      const form = $('form-ip');\n      const n = M.inteiro(lido(form, 'n', 'Tamanho da amostra'), 'Tamanho da amostra');\n      // Lê o texto inteiro para não perder o símbolo %. A matemática decide qual modo usar.\n      const dado = M.lerCaracteristica(form.elements.namedItem('sucessos').value, n);\n      $('ip-proporcao').textContent = `${percentual(dado.p)} com a característica`;\n    } catch (_) { $('ip-proporcao').textContent = '—'; }\n  }\n  // Calcula o erro atual para descobrir como diminuir a margem.\n  function atualizarErro() {\n    try {\n      const form = $('form-de');\n      const desvio = lido(form, 'desvio', 'Desvio-padrão');\n      const n = M.inteiro(lido(form, 'n', 'Tamanho atual da amostra'), 'Tamanho atual da amostra');\n      const e = M.valorCritico(confianca(form)) * desvio / Math.sqrt(n);\n      $('de-atual').textContent = desvio > 0 ? fmt(e, 6) : '—';\n    } catch (_) { $('de-atual').textContent = '—'; }\n  }\n\n  // Cada operação usa EXCLUSIVAMENTE as funções matemáticas do arquivo calculos.js.\n  function executar(id, form) {\n    // Estas funções só transformam números em texto. Não mudam a conta.\n    // Nos intervalos de confiança (IM e IP), os resultados visíveis arredondam para cima.\n    // Exemplo: 1,231 vira 1,24 com duas casas; -1,231 vira -1,23 (em direção ao maior número).\n    // Nas demais abas, a exibição usa o arredondamento normal. O valor completo não arredonda.\n    // Nenhuma opção altera os valores guardados nem as contas feitas com eles.\n    const paraCima = id === 'im' || id === 'ip';\n    // Alguns navegadores antigos não conhecem roundingMode. Este teste detecta isso.\n    const aceitaCeil = new Intl.NumberFormat('pt-BR', {roundingMode:'ceil'}).resolvedOptions().roundingMode === 'ceil';\n    // Deslocar a vírgula pela notação científica evita erros de multiplicação como 0,07 × 100.\n    const deslocar = (n, k) => {\n      const [coef, expoente = '0'] = String(n).split('e');\n      return Number(coef + 'e' + (Number(expoente) + k));\n    };\n    const formatar = (n, casas, estilo = 'decimal') => {\n      if (casas === 'completo') return n.toLocaleString('pt-BR', {style:estilo, maximumSignificantDigits:21});\n      const opcoes = {style:estilo, minimumFractionDigits:casas, maximumFractionDigits:casas};\n      if (paraCima && aceitaCeil) opcoes.roundingMode = 'ceil';\n      if (paraCima && !aceitaCeil) {\n        // Alternativa para navegadores antigos: desloca, arredonda para cima e volta a vírgula.\n        const k = casas + (estilo === 'percent' ? 2 : 0);\n        const ampliado = deslocar(n, k);\n        if (Number.isFinite(ampliado)) n = deslocar(Math.ceil(ampliado), -k);\n      }\n      return n.toLocaleString('pt-BR', opcoes);\n    };\n    const dec = (n, casas) => formatar(n, casas);\n    // O próprio navegador transforma a fração em porcentagem sem multiplicações extras.\n    const pct = (p, casas) => formatar(p, casas, 'percent');\n    const z = M.valorCritico(confianca(form));\n    // A resolução matemática usa os mesmos números da resposta, sem refazer a conta.\n    // x mostra um número sem limitar suas casas; F representa uma fração (parte de cima e de baixo).\n    const x = n => dec(n, 'completo');\n    const F = (numerador, denominador) => ({numerador, denominador});\n    // Cada linha é uma lista de textos e frações, na ordem em que aparecem no papel.\n    // O sinal ≈ indica que o número exibido pode ter sido arredondado.\n    const eq = (...partes) => partes;\n    const fim = (n, casas) => ' ≈ ' + dec(n, casas);\n    // O tamanho mínimo é sempre inteiro: não podemos pesquisar uma parte de uma pessoa.\n    // A frase mostra também o resultado decimal ANTES de arredondar para cima.\n    // Assim, ao clicar em mais casas, a frase acompanha a precisão escolhida.\n    // AM: número mínimo de medições para estimar uma média.\n    if (id === 'am') {\n      const r = M.amostraMedia({confianca: confianca(form), desvio: lido(form, 'desvio', 'Desvio-padrão'), erro: lido(form, 'erro', 'Erro máximo')});\n      return (casas = 2) => ({\n        titulo: 'Tamanho mínimo da amostra', valor: `n = ${fmt(r.n, 0)}`,\n        frase: `O cálculo resulta em ${dec(r.exato, casas)}. Arredondando para cima, são necessárias pelo menos ${fmt(r.n, 0)} observações para estimar a média com ${confianca(form)}% de confiança.`,\n        extras: [['Antes de arredondar', dec(r.exato, casas)]],\n        formulas: [\n          ['Fórmula original', eq('n = (', F('Z · σ', 'Em'), ')²')],\n          ['Substituindo os valores', eq('n = (', F(x(z) + ' · ' + x(r.desvio), x(r.erro)), ')²')],\n          ['Resultado do cálculo', eq('n', fim(r.exato, casas))],\n          ['Tamanho mínimo (arredondando para cima)', eq('n = ', fmt(r.n, 0))]\n        ],\n        passos: [\n          ['Identificar o valor crítico', `Para ${confianca(form)}% de confiança, usamos Z = ${fmt(z, 3)}.`],\n          ['Substituir na fórmula', `n = (${fmt(z, 3)} × ${dec(r.desvio, 'completo')} ÷ ${dec(r.erro, 'completo')})² ≈ ${dec(r.exato, casas)}.`],\n          ['Arredondar para cima', `Precisamos de ${fmt(r.n, 0)} observações, pois não existe uma fração de pessoa ou medição.`]\n        ]\n      });\n    }\n    // AP: número mínimo de pessoas ou itens para estimar uma porcentagem.\n    if (id === 'ap') {\n      const p = $('ap-desconhecida').checked ? 50 : lido(form, 'p', 'Proporção estimada');\n      const r = M.amostraProporcao({confianca: confianca(form), percentual: p, erro: lido(form, 'erro', 'Erro da proporção')});\n      return (casas = 2) => ({\n        titulo: 'Tamanho mínimo da amostra', valor: `n = ${fmt(r.n, 0)}`,\n        frase: `O cálculo resulta em ${dec(r.exato, casas)}. Arredondando para cima, são necessárias pelo menos ${fmt(r.n, 0)} observações para estimar a proporção com ${confianca(form)}% de confiança.`,\n        extras: [['Proporção (p)', pct(r.p, casas)], ['Complemento (1 − p)', pct(r.q, casas)], ['Antes de arredondar', dec(r.exato, casas)]],\n        formulas: [\n          ['Fórmula original', eq('n = ', F('Z² · p · (1 − p)', 'Ep²'))],\n          ['Transformando os percentuais', eq('p = ', F(x(p), '100'), ' = ' + x(r.p) + '; 1 − p = ' + x(r.q) + '; Ep = ' + x(r.ep))],\n          ['Substituindo os valores', eq('n = ', F(x(z) + '² · ' + x(r.p) + ' · ' + x(r.q), x(r.ep) + '²'))],\n          ['Resultado do cálculo', eq('n', fim(r.exato, casas))],\n          ['Tamanho mínimo (arredondando para cima)', eq('n = ', fmt(r.n, 0))]\n        ],\n        passos: [\n          ['Transformar porcentagens em decimais', `p = ${dec(r.p, 'completo')}, complemento = ${dec(r.q, 'completo')} e Ep = ${dec(r.ep, 'completo')}.`],\n          ['Aplicar a fórmula', `n = ${fmt(z, 3)}² × ${dec(r.p, 'completo')} × ${dec(r.q, 'completo')} ÷ ${dec(r.ep, 'completo')}² ≈ ${dec(r.exato, casas)}.`],\n          ['Arredondar para cima', `A amostra mínima é de ${fmt(r.n, 0)} observações.`]\n        ]\n      });\n    }\n    // IM: média menos a margem e média mais a margem.\n    if (id === 'im') {\n      const r = M.intervaloMedia({confianca: confianca(form), media: lido(form, 'media', 'Média amostral'), desvio: lido(form, 'desvio', 'Desvio-padrão'), n: lido(form, 'n', 'Tamanho da amostra')});\n      return (casas = 2) => ({\n        grafico: { inferior: dec(r.inferior, casas), centro: dec(r.media, casas), superior: dec(r.superior, casas), rotulo: 'Média amostral', pontual: r.inferior === r.superior },\n        titulo: 'Intervalo de confiança', valor: `${dec(r.inferior, casas)} a ${dec(r.superior, casas)}`,\n        frase: `Com ${confianca(form)}% de confiança, estimamos a média populacional entre ${dec(r.inferior, casas)} e ${dec(r.superior, casas)}.`,\n        extras: [['Margem de erro (Em)', dec(r.margem, casas)], ['Limite inferior', dec(r.inferior, casas)], ['Limite superior', dec(r.superior, casas)]],\n        formulas: [\n          ['Fórmula da margem de erro', eq('Em = ', F('Z · σ', '√n'))],\n          ['Substituindo os valores', eq('Em = ', F(x(z) + ' · ' + x(r.desvio), '√' + fmt(r.n, 0)), fim(r.margem, casas))],\n          ['Fórmula do intervalo', eq('IC = x̄ ± Em')],\n          ['Limite inferior', eq('x̄ − Em = ' + x(r.media) + ' − ' + x(r.margem), fim(r.inferior, casas))],\n          ['Limite superior', eq('x̄ + Em = ' + x(r.media) + ' + ' + x(r.margem), fim(r.superior, casas))],\n          ['Intervalo de confiança', eq('IC ≈ [' + dec(r.inferior, casas) + ' ; ' + dec(r.superior, casas) + ']')]\n        ],\n        aviso: [r.aviso, casas === 'completo' ? '' : 'Exibição arredondada para cima. Para conferir os limites originais, selecione Valor completo.'].filter(Boolean).join(' '),\n        passos: [\n          ['Escolher o valor crítico', `Para ${confianca(form)}% de confiança, usamos Z = ${fmt(z, 3)}.`],\n          ['Calcular a margem de erro', `Em = ${fmt(z, 3)} × ${dec(r.desvio, 'completo')} ÷ √${fmt(r.n, 0)} ≈ ${dec(r.margem, casas)}.`],\n          ['Encontrar os dois limites', `${dec(r.media, 'completo')} − ${dec(r.margem, 'completo')} ≈ ${dec(r.inferior, casas)}; ${dec(r.media, 'completo')} + ${dec(r.margem, 'completo')} ≈ ${dec(r.superior, casas)}.`]\n        ]\n      });\n    }\n    // IP: proporção menos a margem e proporção mais a margem.\n    if (id === 'ip') {\n      const padraoTexto = form.elements.namedItem('padrao').value.trim();\n      const r = M.intervaloProporcao({confianca: confianca(form), sucessos: form.elements.namedItem('sucessos').value, n: lido(form, 'n', 'Tamanho da amostra'), padrao: padraoTexto ? lido(form, 'padrao', 'Padrão estabelecido') : null});\n      let comparacao = '';\n      if (r.padrao !== null) comparacao = r.atendePadrao\n        ? `Considerando os valores sem arredondar, o limite superior está abaixo do padrão de ${dec(r.padrao, 'completo')}%. Pelo critério informado, a condição foi atendida.`\n        : `Considerando os valores sem arredondar, o intervalo não fica inteiro abaixo do padrão de ${dec(r.padrao, 'completo')}%. Não dá para garantir a condição.`;\n      return (casas = 2) => ({\n        grafico: { inferior: pct(r.inferior, casas), centro: pct(r.p, casas), superior: pct(r.superior, casas), rotulo: 'Proporção amostral', pontual: r.inferior === r.superior },\n        titulo: 'Intervalo de confiança', valor: `${pct(r.inferior, casas)} a ${pct(r.superior, casas)}`,\n        frase: `Com ${confianca(form)}% de confiança, estimamos a proporção populacional entre ${pct(r.inferior, casas)} e ${pct(r.superior, casas)}.`,\n        extras: [['Com a característica', pct(r.p, casas)], ['Sem a característica', pct(r.q, casas)], ['Margem de erro', `${dec(deslocar(r.margem, 2), casas)} pontos percentuais`]],\n        formulas: [\n          ['Proporção amostral', r.percentualInformado === null\n            ? eq('p = ', F('sucessos', 'n'), ' = ', F(fmt(r.sucessos, 0), fmt(r.n, 0)), ' ≈ ' + x(r.p))\n            : eq('p = ', F(x(r.percentualInformado), '100'), ' = ' + x(r.p))],\n          ['Complemento', eq('1 − p = 1 − ' + x(r.p) + ' ≈ ' + x(r.q))],\n          ['Fórmula da margem de erro', eq('Ep = Z · √(p · (1 − p) / n)')],\n          ['Substituindo os valores', eq('Ep = ' + x(z) + ' · √(', F(x(r.p) + ' · ' + x(r.q), fmt(r.n, 0)), ') ≈ ' + x(r.margem))],\n          ['Fórmula do intervalo', eq('IC = p ± Ep')],\n          ['Limite inferior', eq('p − Ep = ' + x(r.p) + ' − ' + x(r.margem) + ' ≈ ' + pct(r.inferior, casas))],\n          ['Limite superior', eq('p + Ep = ' + x(r.p) + ' + ' + x(r.margem) + ' ≈ ' + pct(r.superior, casas))],\n          ['Intervalo de confiança', eq('IC ≈ [' + pct(r.inferior, casas) + ' ; ' + pct(r.superior, casas) + ']')]\n        ],\n        aviso: [...r.avisos, comparacao, casas === 'completo' ? '' : 'Exibição arredondada para cima. Para conferir os limites originais, selecione Valor completo.'].filter(Boolean).join(' '),\n        passos: [\n          // Se o exercício já der a porcentagem, basta dividir por 100, sem descobrir uma contagem.\n          ['Encontrar a proporção', r.percentualInformado === null\n            ? `p = ${fmt(r.sucessos, 0)} ÷ ${fmt(r.n, 0)} = ${dec(r.p, 'completo')}; complemento = ${dec(r.q, 'completo')}.`\n            : `p = ${dec(r.percentualInformado, 'completo')}% ÷ 100 = ${dec(r.p, 'completo')}; complemento = ${dec(r.q, 'completo')}.`],\n          ['Calcular a margem de erro', `Ep = ${fmt(z, 3)} × √(${dec(r.p, 'completo')} × ${dec(r.q, 'completo')} ÷ ${fmt(r.n, 0)}) = ${dec(r.margem, 'completo')}, ou ${dec(deslocar(r.margem, 2), casas)} pontos percentuais.`],\n          ['Encontrar os limites', `Subtraímos e somamos a margem à proporção: ${pct(r.inferior, casas)} a ${pct(r.superior, casas)}.`]\n        ]\n      });\n    }\n    // DE: calcula a nova amostra quando o erro precisa diminuir.\n    if (id === 'de') {\n      const r = M.diminuirErro({confianca: confianca(form), desvio: lido(form, 'desvio', 'Desvio-padrão'), n: lido(form, 'n', 'Tamanho atual da amostra'), fator: lido(form, 'k', 'Dividir o erro por')});\n      return (casas = 2) => ({\n        titulo: 'Novo tamanho da amostra', valor: `n = ${fmt(r.novoN, 0)}`,\n        frase: `O cálculo resulta em ${dec(r.exato, casas)} observações antes de arredondar para cima. Para dividir o erro por ${dec(r.fator, 'completo')} é preciso aumentar a amostra em ${fmt(r.adicionar, 0)} observações, chegando a ${fmt(r.novoN, 0)} no total.`,\n        extras: [['Amostra atual', fmt(r.n, 0)], ['Antes de arredondar', dec(r.exato, casas)], ['Erro atual', dec(r.erroAtual, casas)], ['Novo erro', dec(r.novoErro, casas)], ['Observações adicionais', fmt(r.adicionar, 0)]],\n        formulas: [\n          ['Margem de erro atual', eq('Em = ', F('Z · σ', '√n'), ' = ', F(x(z) + ' · ' + x(r.desvio), '√' + fmt(r.n, 0)), fim(r.erroAtual, casas))],\n          ['Nova margem de erro', eq('Novo Em = ', F('Em', 'k'), ' = ', F(x(r.erroAtual), x(r.fator)), fim(r.novoErro, casas))],\n          ['Fórmula da nova amostra', eq('Novo n = (', F('Z · σ', 'Novo Em'), ')²')],\n          ['Substituindo os valores', eq('Novo n = (', F(x(z) + ' · ' + x(r.desvio), x(r.novoErro)), ')²')],\n          ['Resultado do cálculo', eq('Novo n', fim(r.exato, casas))],\n          ['Tamanho mínimo (arredondando para cima)', eq('Novo n = ' + fmt(r.novoN, 0))],\n          ['Observações adicionais', eq(fmt(r.novoN, 0) + ' − ' + fmt(r.n, 0) + ' = ' + fmt(r.adicionar, 0))]\n        ],\n        passos: [\n          ['Calcular o erro atual', `Em = ${fmt(z, 3)} × ${dec(r.desvio, 'completo')} ÷ √${fmt(r.n, 0)} ≈ ${dec(r.erroAtual, casas)}.`],\n          ['Diminuir o erro', `Novo Em = ${dec(r.erroAtual, 'completo')} ÷ ${dec(r.fator, 'completo')} ≈ ${dec(r.novoErro, casas)}.`],\n          ['Recalcular a amostra', `Novo n = (${fmt(z, 3)} × ${dec(r.desvio, 'completo')} ÷ ${dec(r.novoErro, 'completo')})² ≈ ${dec(r.exato, casas)}. Arredondamos para ${fmt(r.novoN, 0)}.`]\n        ]\n      });\n    }\n    throw new Error('Cálculo não encontrado.');\n  }\n\n  // Cria o resultado usando apenas textContent: entradas não viram HTML.\n  function colocarTexto(elemento, classe, texto) {\n    const filho = document.createElement(elemento);\n    filho.className = classe;\n    filho.textContent = texto;\n    return filho;\n  }\n  // O gráfico é uma régua do intervalo: a ponta esquerda é o menor valor,\n  // a ponta direita é o maior, e a bolinha é a média ou proporção da amostra.\n  // Ele usa os mesmos números da resposta, sem fazer outra conta matemática.\n  function criarGrafico(intervalo) {\n    const figura = document.createElement('figure');\n    figura.className = 'grafico-ic';\n    figura.append(colocarTexto('figcaption', '', 'Visualização do intervalo de confiança'));\n\n    // Três colunas deixam os textos legíveis até na tela de um celular.\n    const rotulos = colocarTexto('div', 'grafico-rotulos', '');\n    for (const [nome, valor] of [\n      ['Limite inferior', intervalo.inferior],\n      [intervalo.rotulo, intervalo.centro],\n      ['Limite superior', intervalo.superior]\n    ]) {\n      const coluna = colocarTexto('div', '', '');\n      coluna.append(colocarTexto('span', '', nome), colocarTexto('strong', '', valor));\n      rotulos.append(coluna);\n    }\n\n    // A linha de fundo é apenas uma referência visual, não uma escala absoluta.\n    // Quando os limites são iguais, a linha azul vira somente um ponto.\n    const regua = colocarTexto('div', 'grafico-regua' + (intervalo.pontual ? ' pontual' : ''), '');\n    regua.setAttribute('aria-hidden', 'true');\n    regua.append(colocarTexto('div', 'grafico-faixa', ''), colocarTexto('span', 'grafico-centro', ''));\n    figura.append(regua, rotulos);\n    figura.append(colocarTexto('p', 'grafico-nota', intervalo.pontual\n      ? 'Os dois limites coincidem: a margem de erro calculada é nula ou indistinguível na precisão numérica.'\n      : 'A linha azul representa a faixa estimada. O ponto central é o valor da amostra.'));\n    return figura;\n  }\n\n  // RESOLUÇÃO COM FÓRMULA: monta expressões com frações de verdade, como no caderno.\n  // Usamos elementos HTML e textContent, não HTML vindo dos dados digitados.\n  function criarResolucaoFormula(formulas) {\n    const bloco = colocarTexto('div', 'contas-formula', '');\n    for (const [rotulo, partes] of formulas) {\n      const linha = colocarTexto('div', 'conta-formula', '');\n      linha.append(colocarTexto('span', 'conta-rotulo', rotulo));\n      const expressao = colocarTexto('div', 'conta-expressao', '');\n      for (const parte of partes) {\n        if (typeof parte === 'string') {\n          expressao.append(colocarTexto('span', 'conta-texto', parte));\n        } else {\n          // Uma fração é composta por dois textos separados por uma linha horizontal.\n          const fracao = colocarTexto('span', 'conta-fracao', '');\n          fracao.append(colocarTexto('span', 'conta-numerador', parte.numerador),\n            colocarTexto('span', 'conta-denominador', parte.denominador));\n          // O texto alternativo ajuda quem usa leitor de tela.\n          fracao.setAttribute('role', 'math');\n          fracao.setAttribute('aria-label', parte.numerador + ' dividido por ' + parte.denominador);\n          expressao.append(fracao);\n        }\n      }\n      linha.append(expressao);\n      bloco.append(linha);\n    }\n    return bloco;\n  }\n\n  // IMPRESSÃO: prepara uma cópia organizada da resolução para a folha de papel.\n  // Esta cópia fica escondida na tela. O CSS só a revela no modo de impressão.\n  // Não existe servidor de PDF: o navegador consegue salvar a folha como PDF sozinho.\n  function criarRelatorio(secao, painel, lista) {\n    const relatorio = colocarTexto('article', 'relatorio-impressao', '');\n    relatorio.append(colocarTexto('p', 'relatorio-marca', 'ESTATÍSTICA APLICADA • RESOLUÇÃO'));\n    relatorio.append(colocarTexto('h2', '', secao.querySelector('h2').textContent));\n    // O PDF identifica a opção escolhida e usa os mesmos números da tela.\n    const precisaoAtiva = painel.querySelector('.precisao[aria-pressed=\"true\"]');\n    if (precisaoAtiva) relatorio.append(colocarTexto('p', 'relatorio-precisao', 'Precisão: ' + precisaoAtiva.textContent));\n\n    // Copia os nomes dos campos e os valores que foram usados na conta.\n    const dados = colocarTexto('section', 'relatorio-bloco', '');\n    dados.append(colocarTexto('h3', '', 'Dados do exercício'));\n    const tabela = colocarTexto('dl', 'relatorio-dados', '');\n    const form = secao.querySelector('form.dados');\n    for (const rotulo of form.querySelectorAll('label[for]')) {\n      const campo = document.getElementById(rotulo.htmlFor);\n      if (!campo) continue;\n      // Se a proporção é desconhecida, a fórmula usa 50% mesmo com o campo desativado.\n      const valor = campo.id === 'ap-p' && campo.disabled\n        ? '50% (proporção desconhecida)'\n        : campo.tagName === 'SELECT'\n          ? (campo.selectedOptions[0]?.textContent || campo.value)\n          : campo.value.trim();\n      if (!valor) continue; // Não imprime campos opcionais que ficaram vazios.\n      tabela.append(colocarTexto('dt', '', rotulo.textContent.trim()), colocarTexto('dd', '', valor));\n    }\n    const z = form.querySelector('[data-z]');\n    if (z) tabela.append(colocarTexto('dt', '', 'Valor crítico'), colocarTexto('dd', '', z.textContent));\n    dados.append(tabela);\n    relatorio.append(dados);\n\n    // Copia as fórmulas mostradas na aba selecionada, sem duplicar a matemática.\n    const formulas = colocarTexto('section', 'relatorio-bloco', '');\n    formulas.append(colocarTexto('h3', '', 'Fórmula utilizada'));\n    for (const expressao of secao.querySelectorAll('.formula .expressao')) {\n      formulas.append(colocarTexto('p', 'relatorio-formula', expressao.textContent));\n    }\n    relatorio.append(formulas);\n\n    // A resposta, os valores intermediários e o gráfico já estão prontos.\n    // cloneNode(true) faz uma cópia, sem retirar nada da tela original.\n    const resposta = colocarTexto('section', 'relatorio-bloco', '');\n    resposta.append(colocarTexto('h3', '', 'Resposta do exercício'));\n    for (const classe of ['.numero-resposta', '.frase-resposta', '.extras', '.grafico-ic', '.aviso']) {\n      const item = painel.querySelector(classe);\n      if (item) resposta.append(item.cloneNode(true));\n    }\n    relatorio.append(resposta);\n\n    // O passo a passo sai completo mesmo se estiver recolhido na tela.\n    const passos = colocarTexto('section', 'relatorio-bloco passos', '');\n    passos.append(colocarTexto('h3', '', 'Resolução passo a passo'), lista.cloneNode(true));\n    relatorio.append(passos);\n    // A resolução matemática também sai no PDF, mesmo que esteja fechada na tela.\n    const contas = painel.querySelector('.contas-formula');\n    if (contas) {\n      const secaoFormula = colocarTexto('section', 'relatorio-bloco', '');\n      secaoFormula.append(colocarTexto('h3', '', 'Resolução com fórmula'), contas.cloneNode(true));\n      relatorio.append(secaoFormula);\n    }\n    return relatorio;\n  }\n\n  // A resposta é uma função que lembra os valores da conta original.\n  // As três opções são 0 casas, 2 casas (padrão) e precisão completa.\n  function mostrarResultado(secao, criarResposta, casas = 2, aberto = false, focar = false, formulaAberta = false) {\n    const resposta = criarResposta(casas);\n    const painel = secao.querySelector('.resultado');\n    painel.replaceChildren();\n    const resumo = colocarTexto('div', 'resposta-superior', 'RESPOSTA DO EXERCÍCIO');\n    const valor = colocarTexto('strong', 'numero-resposta', resposta.valor);\n    const frase = colocarTexto('p', 'frase-resposta', resposta.frase);\n    // Cada botão seleciona uma apresentação do mesmo resultado, sem refazer a conta.\n    const controles = colocarTexto('div', 'precisao-opcoes', '');\n    controles.setAttribute('role', 'group');\n    controles.setAttribute('aria-label', 'Arredondamento dos resultados');\n    let botaoAtivo;\n    for (const [modo, nome] of [[0, 'Sem casas decimais'], [2, '2 casas decimais'], ['completo', 'Valor completo']]) {\n      const botao = colocarTexto('button', 'precisao', nome);\n      botao.type = 'button';\n      botao.dataset.precisao = String(modo);\n      botao.setAttribute('aria-pressed', String(casas === modo));\n      if (casas === modo) botaoAtivo = botao;\n      botao.addEventListener('click', () => {\n        if (casas !== modo) mostrarResultado(secao, criarResposta, modo, detalhes.open, true, detalhesFormula.open);\n      });\n      controles.append(botao);\n    }\n    painel.append(resumo, valor, controles, frase);\n\n    if (resposta.extras?.length) {\n      const tabela = colocarTexto('div', 'extras', '');\n      for (const [nome, dado] of resposta.extras) {\n        const linha = colocarTexto('div', 'extra-linha', '');\n        linha.append(colocarTexto('span', '', nome), colocarTexto('strong', '', dado));\n        tabela.append(linha);\n      }\n      painel.append(tabela);\n    }\n    // Só os intervalos de confiança têm uma régua de limites.\n    if (resposta.grafico) painel.append(criarGrafico(resposta.grafico));\n    if (resposta.aviso) painel.append(colocarTexto('p', 'aviso', resposta.aviso));\n    const detalhes = document.createElement('details');\n    detalhes.className = 'passos';\n    // Se o passo a passo estava aberto, continua aberto.\n    detalhes.open = aberto;\n    const titulo = document.createElement('summary');\n    titulo.textContent = 'Ver resolução passo a passo';\n    detalhes.append(titulo);\n    const lista = document.createElement('ol');\n    resposta.passos.forEach(([nome, explicacao]) => {\n      const passo = document.createElement('li');\n      passo.append(colocarTexto('strong', '', nome), colocarTexto('p', '', explicacao));\n      lista.append(passo);\n    });\n    detalhes.append(lista);\n    painel.append(detalhes);\n\n    // A nova seção é independente do passo a passo e começa recolhida.\n    // Ao alterar a precisão, preservamos o estado aberto/fechado das duas seções.\n    const detalhesFormula = document.createElement('details');\n    detalhesFormula.className = 'passos resolucao-formula';\n    detalhesFormula.open = formulaAberta;\n    const tituloFormula = colocarTexto('summary', '', 'Ver resolução com fórmula');\n    detalhesFormula.append(tituloFormula, criarResolucaoFormula(resposta.formulas));\n    painel.append(detalhesFormula);\n\n    // O botão aparece só depois que uma conta foi resolvida com sucesso.\n    // window.print abre a janela nativa: escolha \"Salvar como PDF\" como destino.\n    const imprimir = colocarTexto('button', 'imprimir-pdf', 'Imprimir / Salvar em PDF');\n    imprimir.type = 'button';\n    imprimir.addEventListener('click', () => window.print());\n    painel.append(imprimir, criarRelatorio(secao, painel, lista));\n    painel.hidden = false;\n    // Devolve o foco ao botão para quem navega com o teclado.\n    if (focar) botaoAtivo?.focus({preventScroll:true});\n  }\n\n  // A entrada mudou: esconde o resultado anterior para não confundir cálculos.\n  for (const form of document.querySelectorAll('form.dados')) {\n    const secao = form.closest('.assunto');\n    const aviso = form.querySelector('.erro');\n    const resultado = secao.querySelector('.resultado');\n    // Ao clicar Calcular, impede o recarregamento da página e mostra a resposta.\n    form.addEventListener('submit', evento => {\n      evento.preventDefault();\n      aviso.hidden = true;\n      resultado.hidden = true;\n      try { mostrarResultado(secao, executar(form.id.slice(5), form)); }\n      catch (erro) {\n        aviso.textContent = erro instanceof Error ? erro.message : 'Não foi possível calcular. Revise os valores.';\n        aviso.hidden = false;\n      }\n    });\n    // A cada digitação, esconde a resposta antiga.\n    form.addEventListener('input', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      atualizarComplemento(); atualizarProporcao(); atualizarErro();\n    });\n    // Atualiza os valores automáticos quando uma seleção muda.\n    form.addEventListener('change', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      atualizarZ(form); atualizarComplemento(); atualizarProporcao(); atualizarErro();\n    });\n    // Ao clicar Limpar, apaga resposta e mensagens de erro.\n    form.addEventListener('reset', () => {\n      resultado.hidden = true;\n      aviso.hidden = true;\n      // Os valores só voltam ao padrão após o evento reset terminar.\n      queueMicrotask(() => { atualizarZ(form); atualizarComplemento(); atualizarProporcao(); atualizarErro(); });\n    });\n    atualizarZ(form);\n  }\n  document.querySelectorAll('[data-aba]').forEach(botao => {\n    botao.addEventListener('click', () => abrirAba(botao.dataset.aba));\n  });\n  atualizarComplemento(); atualizarProporcao(); atualizarErro(); abrirAba('am');\n})();\n","/src/exemplos.js":"/* Exercícios adaptados dos três PDFs da disciplina, com números novos.\n * Cada caso contém somente os campos da calculadora que o resolve.\n * Em comparações há mais de um botão; nenhum deles revela a resposta sozinho.\n */\n(function (global) {\n  'use strict';\n  // Cada cenário guarda o texto do botão e os valores que serão preenchidos.\n  const caso = (rotulo, campos) => ({rotulo, campos});\n  // Cada linha tem código, aba, título, enunciado e cenários de treino.\n  const exemplos = [\n    ['A1','am','Tempo de resposta de API','Uma API tem desvio-padrão populacional de 980 ms. Com 95% de confiança e erro máximo de 75 ms, quantas requisições devem ser medidas?',[caso('Preencher dados',{confianca:95,desvio:980,erro:75})]],\n    ['A2','am','Comparar graus de confiança','Para uma API com σ = 870 ms e Em = 65 ms, compare as amostras mínimas com 90%, 95% e 99% de confiança.',[90,95,99].map(confianca=>caso(`${confianca}% de confiança`,{confianca,desvio:870,erro:65}))],\n    ['A3','ap','Pesquisa eleitoral','Uma pesquisa estima 42% de intenção de voto. Qual amostra mínima permite erro de 2,5% com 95% de confiança?',[caso('Preencher dados',{confianca:95,p:42,erro:'2,5'})]],\n    ['A4','ap','Falhas de software','Uma equipe de QA estima que 18% dos testes falham. Com 99% de confiança e erro de 4%, calcule a amostra mínima. Repita quando a proporção for desconhecida.',[caso('Proporção conhecida',{confianca:99,p:18,erro:4}),caso('Proporção desconhecida',{confianca:99,desconhecida:true,erro:4})]],\n    ['B1','im','Altura dos estudantes','Uma amostra de 64 estudantes tem altura média de 1,69 m e desvio-padrão de 0,16 m. Determine o IC de 95%.',[caso('Preencher dados',{confianca:95,media:'1,69',desvio:'0,16',n:64})]],\n    ['B2','im','Altura com 90% de confiança','Uma amostra de 64 estudantes tem média de 1,69 m e desvio-padrão de 0,16 m. Determine o IC de 90%.',[caso('Preencher dados',{confianca:90,media:'1,69',desvio:'0,16',n:64})]],\n    ['B3','im','Altura com 99% de confiança','Uma amostra de 64 estudantes tem média de 1,69 m e desvio-padrão de 0,16 m. Determine o IC de 99%.',[caso('Preencher dados',{confianca:99,media:'1,69',desvio:'0,16',n:64})]],\n    ['B4','im','Efeito do tamanho da amostra','Para altura média de 1,69 m, desvio-padrão de 0,16 m e confiança de 99%, compare os intervalos com 64 e 144 estudantes.',[64,144].map(n=>caso(`n = ${n}`,{confianca:99,media:'1,69',desvio:'0,16',n}))],\n    ['B5','im','Tempo de resposta de servidor','Em 81 requisições, o tempo médio foi de 275 ms e o desvio-padrão de 38 ms. Calcule o IC de 95%.',[caso('Preencher dados',{confianca:95,media:275,desvio:38,n:81})]],\n    ['B6','im','Consumo de memória RAM','Em 49 execuções, o consumo médio foi de 3,4 GB, com desvio-padrão de 0,55 GB. Estime a média populacional com 99% de confiança.',[caso('Preencher dados',{confianca:99,media:'3,4',desvio:'0,55',n:49})]],\n    ['B7','im','Duração de sessões','Em 72 sessões de uma plataforma, a duração média foi de 21,4 minutos, com desvio-padrão de 5,1 minutos. Determine o IC de 90%.',[caso('Preencher dados',{confianca:90,media:'21,4',desvio:'5,1',n:72})]],\n    ['C1','ip','Intenção de voto','Em uma pesquisa com 1.850 eleitores, 703 declararam intenção de votar em um candidato. Construa o IC de 95%.',[caso('Preencher dados',{confianca:95,sucessos:703,n:1850})]],\n    ['C2','ip','Preferência por barbeador','Entre 240 entrevistados, 87 preferem determinada marca de barbeador. Determine o IC de 90% para essa preferência.',[caso('Preencher dados',{confianca:90,sucessos:87,n:240})]],\n    ['C3','ip','Etiquetas sem defeitos','Em 680 etiquetas examinadas, 46 estavam defeituosas. Estime, com 95% de confiança, a proporção de etiquetas sem defeitos. Informe a quantidade que interessa.',[caso('Preencher dados',{confianca:95,sucessos:634,n:680})]],\n    ['C4','ip','Taxa de desemprego','Uma amostra de 1.240 habitantes em idade de trabalhar contém 103 desempregados. Estime a proporção de desempregados com 95% de confiança.',[caso('Preencher dados',{confianca:95,sucessos:103,n:1240})]],\n    ['C5','ip','Taxa de bugs','Em 320 módulos de software, 41 têm bugs críticos. Construa o IC de 95% e verifique se a taxa está abaixo do padrão estabelecido de 18%.',[caso('Preencher dados',{confianca:95,sucessos:41,n:320,padrao:18})]],\n    ['C6','ip','Autenticação em dois fatores','Entre 720 usuários, 478 utilizam autenticação em dois fatores. Determine o IC de 99% para a adoção.',[caso('Preencher dados',{confianca:99,sucessos:478,n:720})]],\n    ['C7','ip','Satisfação com aplicativo','Em 950 usuários pesquisados, 684 avaliaram positivamente o aplicativo. Construa o IC de 95% para a proporção de satisfeitos.',[caso('Preencher dados',{confianca:95,sucessos:684,n:950})]],\n    ['T1','de','Diminuir a margem de erro','Uma amostra de 80 medições tem desvio-padrão de 14,5. Com 95% de confiança, quantas observações adicionais são necessárias para reduzir a margem de erro a um terço?',[caso('Preencher dados',{confianca:95,desvio:'14,5',n:80,k:3})]]\n  ];\n  global.ExemplosEstatistica = exemplos;\n  if (typeof document === 'undefined') return;\n  const lista = document.getElementById('lista-exemplos');\n  if (!lista) return;\n  const grupos = {am:'Tamanho da amostra — média',ap:'Tamanho da amostra — proporção',im:'Intervalo de confiança — média',ip:'Intervalo de confiança — proporção',de:'Diminuir o erro — treino extra'};\n  // O botão usa os controles existentes: limpa o caso anterior e preenche o novo.\n  function carregar(aba, campos) {\n    const form = document.getElementById(`form-${aba}`);\n    const tab = document.querySelector(`.aba[data-aba=\"${aba}\"]`);\n    if (!form || !tab) return;\n    // Apaga os campos antigos antes de colocar os novos.\n    form.reset();\n    for (const [nome, valor] of Object.entries(campos)) {\n      const campo = form.elements.namedItem(nome);\n      if (!campo) continue;\n      if (campo.type === 'checkbox') campo.checked = Boolean(valor);\n      else campo.value = String(valor);\n    }\n    // Avisa a interface da mudança e abre a aba correta.\n    form.dispatchEvent(new Event('change', {bubbles:true}));\n    tab.click();\n    form.querySelector('button[type=\"submit\"]').focus();\n  }\n  // Cria um elemento visual e coloca texto nele.\n  function criar(tag, texto, classe) {\n    const el = document.createElement(tag);\n    el.textContent = texto;\n    if (classe) el.className = classe;\n    return el;\n  }\n  // Monta os cartões de exercício, separados por assunto.\n  for (const [aba, titulo] of Object.entries(grupos)) {\n    const grupo = criar('section','','grupo-exemplos');\n    grupo.append(criar('h3',titulo));\n    const grade = criar('div','','grade-exemplos');\n    for (const [codigo,tipo,nome,enunciado,casos] of exemplos) {\n      if (tipo !== aba) continue;\n      const card = criar('article','','cartao exemplo-card');\n      card.append(criar('h4',`${codigo} · ${nome}`),criar('p',enunciado));\n      const acoes = criar('div','','acoes exemplo-acoes');\n      for (const {rotulo,campos} of casos) {\n        const botao = criar('button',rotulo,'limpar');\n        botao.type = 'button';\n        botao.addEventListener('click',()=>carregar(aba,campos));\n        acoes.append(botao);\n      }\n      card.append(acoes);grade.append(card);\n    }\n    grupo.append(grade);lista.append(grupo);\n  }\n})(globalThis);\n","/":"<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <!-- Instruções ao navegador: título, tamanho da tela e arquivos necessários. -->\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#174CA0\">\n  <meta name=\"description\" content=\"Calcule tamanho da amostra e intervalos de confiança, com explicações simples e claras.\">\n  <title>Estatística Aplicada — Calculadora</title>\n  <!-- CSS controla a aparência. JavaScript conecta os campos aos cálculos. -->\n  <link rel=\"stylesheet\" href=\"./assets/style.css\">\n  <script src=\"./src/calculos.js\" defer></script>\n  <script src=\"./src/app.js\" defer></script>\n  <script src=\"./src/exemplos.js\" defer></script>\n</head>\n<body>\n  <header class=\"cabecalho\">\n    <div class=\"largura topo\">\n      <a class=\"marca\" href=\"./\" aria-label=\"Estatística Aplicada — início\">\n        <span class=\"marca-sinal\" aria-hidden=\"true\">Σ</span>\n        <span>Estatística <strong>Aplicada</strong></span>\n      </a>\n      <span class=\"marca-extra\">Calculadora da disciplina</span>\n    </div>\n  </header>\n\n  <main class=\"largura\">\n    <div class=\"introducao\">\n      <span class=\"sobretitulo\">FÓRMULAS DA AULA</span>\n      <h1>Qual cálculo você precisa fazer?</h1>\n      <p>Escolha o assunto, preencha os valores do exercício e veja como chegar à resposta.</p>\n    </div>\n\n    <!-- As cinco abas são os cinco assuntos do index.html de referência. -->\n    <!-- data-aba indica qual seção abrir ao clicar no botão. -->\n    <nav class=\"abas\" aria-label=\"Escolher cálculo\">\n      <button type=\"button\" class=\"aba ativa\" data-aba=\"am\" aria-current=\"page\"><small>Tamanho da amostra</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ap\"><small>Tamanho da amostra</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"im\"><small>Intervalo de confiança</small><strong>Média</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ip\"><small>Intervalo de confiança</small><strong>Proporção</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"de\"><small>Ajuste da amostra</small><strong>Diminuir o erro</strong></button>\n      <button type=\"button\" class=\"aba\" data-aba=\"ex\"><small>Treinar</small><strong>Exemplos</strong></button>\n    </nav>\n\n    <!-- Assunto 1: calcular quantas observações são necessárias para a média. -->\n    <section class=\"assunto visivel\" id=\"aba-am\" aria-labelledby=\"titulo-am\">\n      <h2 id=\"titulo-am\">Tamanho da amostra para a média</h2>\n      <p class=\"descricao\">Quantas observações preciso para estimar uma média com a precisão desejada?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-am\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"am-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"am-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"am\">Z = 1,96</output></div>\n          <label for=\"am-desvio\">Desvio-padrão populacional (σ)</label>\n          <input id=\"am-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"am-erro\">Erro amostral máximo aceito (Em)</label>\n          <input id=\"am-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a margem de erro\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = (Z · σ / Em)²</div><dl><dt>n</dt><dd>Tamanho mínimo da amostra</dd><dt>σ</dt><dd>Desvio-padrão populacional</dd><dt>Em</dt><dd>Erro máximo aceito</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 2: amostra necessária para estimar uma porcentagem. -->\n    <section class=\"assunto\" id=\"aba-ap\" aria-labelledby=\"titulo-ap\" hidden>\n      <h2 id=\"titulo-ap\">Tamanho da amostra para a proporção</h2>\n      <p class=\"descricao\">Quantas pessoas ou observações preciso para estimar uma porcentagem?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-ap\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ap-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ap-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ap\">Z = 1,96</output></div>\n          <label for=\"ap-p\">Proporção estimada (p), em %</label>\n          <input id=\"ap-p\" name=\"p\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a porcentagem\">\n          <label class=\"marcar\"><input type=\"checkbox\" name=\"desconhecida\" id=\"ap-desconhecida\"> Proporção desconhecida (usar 50%)</label>\n          <div class=\"dado-automatico\"><span>Complemento (1 − p)</span><output id=\"ap-complemento\">—</output></div>\n          <label for=\"ap-erro\">Erro da proporção (Ep), em %</label>\n          <input id=\"ap-erro\" name=\"erro\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o erro em %\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmula utilizada</h3><div class=\"expressao\">n = Z² · p · (1 − p) / Ep²</div><dl><dt>p</dt><dd>Proporção estimada</dd><dt>1 − p</dt><dd>Complemento da proporção</dd><dt>Ep</dt><dd>Erro da proporção, em decimal</dd><dt>Z</dt><dd>Valor relacionado à confiança</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 3: intervalo entre dois valores para a média. -->\n    <section class=\"assunto\" id=\"aba-im\" aria-labelledby=\"titulo-im\" hidden>\n      <h2 id=\"titulo-im\">Intervalo de confiança para a média</h2>\n      <p class=\"descricao\">Entre quais valores pode estar a média verdadeira da população?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-im\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"im-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"im-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"im\">Z = 1,96</output></div>\n          <label for=\"im-media\">Média amostral (x̄)</label><input id=\"im-media\" name=\"media\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite a média\">\n          <label for=\"im-desvio\">Desvio-padrão (σ ou s)</label><input id=\"im-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"im-n\">Tamanho da amostra (n)</label><input id=\"im-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite a quantidade\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Em = Z · σ / √n</div><div class=\"expressao\">IC = x̄ ± Em</div><dl><dt>x̄</dt><dd>Média da amostra</dd><dt>Em</dt><dd>Margem de erro calculada</dd><dt>n</dt><dd>Quantidade de observações</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 4: intervalo entre duas porcentagens. -->\n    <section class=\"assunto\" id=\"aba-ip\" aria-labelledby=\"titulo-ip\" hidden>\n      <h2 id=\"titulo-ip\">Intervalo de confiança para a proporção</h2>\n      <p class=\"descricao\">Entre quais porcentagens pode estar a proporção verdadeira da população?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-ip\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"ip-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"ip-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"ip\">Z = 1,96</output></div>\n          <label for=\"ip-sucessos\">Quantidade ou porcentagem com a característica</label><input id=\"ip-sucessos\" name=\"sucessos\" inputmode=\"text\" autocomplete=\"off\" placeholder=\"Ex.: 922 ou 40%\">\n          <label for=\"ip-n\">Tamanho da amostra (n)</label><input id=\"ip-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o total pesquisado\">\n          <div class=\"dado-automatico\"><span>Proporção da amostra</span><output id=\"ip-proporcao\">—</output></div>\n          <label for=\"ip-padrao\">Padrão estabelecido (%) <span class=\"opcional\">— opcional</span></label><input id=\"ip-padrao\" name=\"padrao\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Somente se o exercício pedir\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">p = sucessos / n ou % / 100</div><div class=\"expressao\">Ep = Z · √[p(1 − p) / n]</div><div class=\"expressao\">IC = p ± Ep</div><dl><dt>p</dt><dd>Proporção da amostra</dd><dt>Ep</dt><dd>Margem de erro da proporção</dd><dt>n</dt><dd>Total pesquisado</dd></dl></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <!-- Assunto 5: a amostra cresce quando exigimos erro menor. -->\n    <section class=\"assunto\" id=\"aba-de\" aria-labelledby=\"titulo-de\" hidden>\n      <h2 id=\"titulo-de\">Diminuir o erro da média</h2>\n      <p class=\"descricao\">Se eu quiser um erro menor, quantas observações adicionais serão necessárias?</p>\n      <div class=\"colunas\">\n        <!-- form reúne as entradas; label é o nome visível, input é o espaço para digitar. -->\n        <form class=\"cartao dados\" id=\"form-de\" novalidate>\n          <h3>Dados do exercício</h3>\n          <label for=\"de-confianca\">Grau de confiança</label>\n          <div class=\"confianca\"><select id=\"de-confianca\" name=\"confianca\"><option value=\"90\">90%</option><option value=\"95\" selected>95%</option><option value=\"99\">99%</option></select><output data-z=\"de\">Z = 1,96</output></div>\n          <label for=\"de-desvio\">Desvio-padrão (σ ou s)</label><input id=\"de-desvio\" name=\"desvio\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite o desvio-padrão\">\n          <label for=\"de-n\">Tamanho atual da amostra (n)</label><input id=\"de-n\" name=\"n\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Digite o tamanho atual\">\n          <div class=\"dado-automatico\"><span>Erro atual (Em)</span><output id=\"de-atual\">—</output></div>\n          <label for=\"de-k\">Dividir o erro por quantas vezes?</label><input id=\"de-k\" name=\"k\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"Digite um valor maior que 1\">\n          <div class=\"erro\" role=\"alert\" hidden></div>\n          <div class=\"acoes\"><button class=\"primario\" type=\"submit\">Calcular</button><button class=\"limpar\" type=\"reset\">Limpar</button></div>\n        </form>\n        <aside class=\"cartao formula\"><h3>Fórmulas utilizadas</h3><div class=\"expressao\">Novo Em = Em / k</div><div class=\"expressao\">Novo n = (Z · σ / Novo Em)²</div><dl><dt>k</dt><dd>Quantas vezes o erro vai diminuir</dd><dt>Em</dt><dd>Margem de erro atual</dd><dt>n</dt><dd>Quantidade de observações</dd></dl><p class=\"nota-formula\">Ao reduzir o erro pela metade, precisamos de aproximadamente 4 vezes mais observações.</p></aside>\n      </div>\n      <!-- Espaço vazio: app.js só mostra a resposta depois de Calcular. -->\n      <div class=\"resultado\" hidden></div>\n    </section>\n\n    <section class=\"assunto\" id=\"aba-ex\" aria-labelledby=\"titulo-ex\" hidden>\n      <h2 id=\"titulo-ex\">Exemplos para praticar</h2>\n      <p class=\"descricao\">Exercícios adaptados dos PDFs da aula, com valores diferentes. Preencha os dados e clique em Calcular quando quiser conferir.</p>\n      <div id=\"lista-exemplos\"></div>\n    </section>\n\n    <footer class=\"rodape\"><span>Uma ferramenta de apoio aos exercícios de Estatística Aplicada.</span><span>RFB · 2026</span></footer>\n  </main>\n</body>\n</html>\n"};
export default { async fetch(request) {
  const caminho = new URL(request.url).pathname;
  if (caminho === '/api/saude') return Response.json({ok:true,versao:'1.0.0',modo:'estatico'});
  if (request.method !== 'GET' && request.method !== 'HEAD') return new Response('Método não permitido', {status:405,headers:{Allow:'GET, HEAD'}});
  const arquivo = Object.prototype.hasOwnProperty.call(FILES, caminho) ? FILES[caminho] : undefined;
  if (arquivo === undefined) return new Response('Página não encontrada', {status:404});
  const tipo = caminho.endsWith('.css') ? 'text/css' : caminho.endsWith('.js') ? 'text/javascript' : 'text/html';
  return new Response(request.method === 'HEAD' ? null : arquivo, {status:200,headers:{'Content-Type':tipo+'; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
}};
